-- ABS-01--13 / REV-01--09. Synthetic rollback only. No hosted activity.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir ../support/registration-fixtures.psql
\ir ../support/profile-complete-fixtures.psql
\ir ../support/abstract-fixtures.psql
select is((select count(*) from msrc_abstracts.settings),0::bigint,'No scientific settings seeded');
select ok(not exists(select 1 from pg_class c where c.relnamespace='msrc_abstracts'::regnamespace and c.relkind='r' and not(c.relrowsecurity and c.relforcerowsecurity)),'All abstract tables force RLS without fixed object count');
select ok(not exists(select 1 from pg_policies where schemaname='msrc_abstracts'),'Private tables have no permissive client policies');
select ok(not exists(select 1 from (values('anon'),('authenticated'),('service_role')) r(name) where has_schema_privilege(name,'msrc_abstracts','USAGE')),'No API schema access');
select ok(not exists(select 1 from pg_class c cross join(values('anon'),('authenticated'),('service_role')) r(name) where c.relnamespace='msrc_abstracts'::regnamespace and c.relkind='r' and has_table_privilege(name,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),'No direct API table access');
select ok(not exists(select 1 from pg_proc p where p.pronamespace='msrc_abstracts'::regnamespace and p.prosecdef and not('search_path=""'=any(p.proconfig))),'Private definers pin search_path');
select ok(not exists(select 1 from pg_proc p cross join lateral aclexplode(p.proacl) a where p.pronamespace='msrc_abstracts'::regnamespace and a.grantee in(0,'anon'::regrole,'authenticated'::regrole,'service_role'::regrole)),'No private helper execute ACL');
select ok(not exists(select 1 from pg_proc p cross join lateral aclexplode(p.proacl) a where p.pronamespace='public'::regnamespace and p.proname like 'msrc_abstracts_%' and a.grantee in(0,'anon'::regrole,'authenticated'::regrole)),'Participant RPCs remain server only');
select is(public.msrc_abstracts_status('synthetic-abstracts')->>'enabled','false','Absent settings close abstracts');
