select throws_ok($$select public.msrc_staff_research_list('synthetic-abstracts')$$,'42501',null,'Anonymous staff RPC denied');
reset role;
set local role authenticated;
select throws_ok($$select public.msrc_abstracts_me('synthetic-abstracts','{}'::jsonb)$$,'42501',null,'Clients cannot forge forwarded participant claims');
reset role;
