select is(msrc_abstracts.word_count(jsonb_build_object('background',U&'\00BD \00B2 \2163 \+01E4D0')),10,'Unicode numeric categories and recent letters match JavaScript L/N');
select is(msrc_abstracts.word_count(jsonb_build_object('background',U&'one\0085two\200Bthree')),7,'Non-ECMAScript separators cannot inflate server word count');
