select is(public.msrc_staff_research_scorecard('synthetic-abstracts','e7a00000-0000-4000-8000-000000000002',1,'{"scores":[{"criterionId":"synthetic-criterion","value":7}],"comments":"Late score","recommendation":"accept"}'::jsonb,true)->>'state','locked','Pinned immutable review deadline rejects late scorecard writes');
update msrc_abstracts.mutation_limits set used=60,window_started_at=clock_timestamp() where actor_id=pg_temp.registration_actor(9001);
select is(public.msrc_abstracts_save_draft('synthetic-abstracts',pg_temp.registration_claims(9001),null,0,pg_temp.abstract_document(),gen_random_uuid())->>'state','limited','Independent abstract budget throttles only new mutations');
select is(public.msrc_abstracts_save_draft('synthetic-abstracts',pg_temp.registration_claims(9001),null,0,pg_temp.abstract_document(),'e7900000-0000-4000-8000-000000000001')->>'state','saved','Cached idempotent draft retry does not consume another mutation budget');
select is(public.msrc_abstracts_me('synthetic-abstracts',pg_temp.registration_claims(9001))->>'state','ready','Abstract reads remain available after mutation limit');
select is((select count(*) from msrc_abstracts.audit where event='mutation.limited' and actor_id=pg_temp.registration_actor(9001)),1::bigint,'Mutation budget denial is audited without an unbounded per-attempt log');
update msrc_abstracts.mutation_limits set window_started_at=clock_timestamp()-interval '2 minutes' where actor_id=pg_temp.registration_actor(9001);
select is(public.msrc_abstracts_save_draft('synthetic-abstracts',pg_temp.registration_claims(9001),null,0,pg_temp.abstract_document(),gen_random_uuid())->>'state','submission_used','Expired mutation budget does not restore a used submission chance');
select throws_ok($$update msrc_abstracts.audit set event='tampered'$$,'55000',null,'Audit immutable');
select throws_ok($$update msrc_abstracts.decisions set instructions='tampered'$$,'55000',null,'Decisions immutable');
select throws_ok($$update msrc_abstracts.decisions set review_basis='{}'::jsonb$$,'55000',null,'Scientific decision basis cannot be overwritten');
select throws_ok($$delete from msrc_abstracts.publications$$,'55000',null,'Publication history immutable');
select * from finish();
rollback;
